from copy import deepcopy


class PanelBook:
    def __init__(self, panels):
        if not isinstance(panels, dict) or not panels:
            raise ValueError("panels must be a non-empty dictionary")
        if any(not isinstance(name, str) or not name or not isinstance(content, list) for name, content in panels.items()):
            raise ValueError("panel entries are invalid")
        self._panels = deepcopy(panels)

    def select(self, name):
        if name not in self._panels:
            raise KeyError(name)
        first_name = next(iter(self._panels))
        return deepcopy(self._panels[first_name])

    def names(self):
        return list(self._panels)
